-- =============================================================================
-- PRSME — Phase 9: notifications
-- =============================================================================
--
-- WHAT THIS IS
--
-- One table that records something that happened TO an account: somebody
-- followed it, somebody asked to follow it, somebody's request was approved
-- or declined, somebody commented on it.
--
-- THE ONE THING THIS FILE IS CAREFUL ABOUT
--
-- A notification must never be a way to learn something you were not already
-- allowed to know. The notification text is generated by the DATABASE, not by
-- the application, and it carries only what the recipient is entitled to see:
-- the actor's handle, the kind of event, and the moment it happened. It never
-- carries the content of a comment, because a comment on a private profile is
-- readable by the profile's approved followers, and a notification is a
-- summary of it — the recipient reads the comment itself, under the same
-- rules, on the profile.
--
-- WHY THE NOTIFICATION IS WRITTEN BY A TRIGGER
--
-- Every other rule in this project lives in the database: the follow state
-- machine is a trigger, the block is a trigger, the comment permission is an
-- RLS policy. The notification is the same kind of rule.
--
-- It has to be. The requirement is that a notification exists "only when the
-- relevant relationship or comment action actually succeeds". A notification
-- written by the application would have to be written after the fact, and
-- there is a gap between the write and the notification where the write can
-- fail, or the notification can be written twice, or a retry can duplicate
-- it. A trigger that runs in the SAME transaction as the action that caused it
-- has none of those gaps: if the action rolls back, so does the notification,
-- and if the action commits, so does the notification.
--
-- WHY THE TRIGGER RUNS AS THE TABLE'S OWNER
--
-- The trigger is SECURITY DEFINER, so it can read the actor's profile row
-- even when the recipient could not read it directly — a private profile.
-- Without the definer's rights the trigger could not build the notification's
-- text for a private account at all.
--
-- THE DATA MODEL
--
--   recipient_id    the account being notified
--   actor_id        the account that caused it
--   type            the event, as a closed set of values
--   follow_id       the follow edge, when the event is about one
--   comment_id      the comment, when the event is about one
--   body            the one-line description, built by the database
--   actor_username  the actor's handle, frozen at the moment of the event
--   target_username the recipient's handle, frozen at the same moment
--   read_at         when the recipient read it; NULL means unread
--   dismissed_at    when it stopped being shown; NULL means still on the list
--
-- The two REFERENCES are nullable and exclusive per type, rather than a
-- single polymorphic "entity_id" column with a "entity_type" string beside
-- it. A polymorphic reference cannot be a foreign key, so nothing would
-- guarantee that the id in it points at a row that exists. Two real foreign
-- keys can, and Postgres will refuse a notification whose comment was
-- deleted.
--
-- WHY THE TWO HANDLES ARE FROZEN ONTO THE ROW
--
-- Because the notification must read the same for everybody, and because it
-- must not have to JOIN the profiles table to find out who did something.
--
-- A JOIN would be filtered by the profiles RLS policy, so a notification
-- about a private actor would either vanish (hiding an event the recipient
-- is entitled to know about) or come back carrying a display name the
-- recipient is not entitled to read. Freezing the handles at the moment of
-- the event sidesteps both: the row says who did it and where it happened,
-- and nothing about the actor's profile leaks through it.
--
-- A HANDLE is the right thing to freeze, and a display name is not. A handle
-- is public by construction: the database keeps it unique, and the
-- availability check tells every visitor that a name is taken without telling
-- them WHO holds it. A display name is part of a profile's identity, and a
-- private profile's owner has not agreed to share it — a stranger's request
-- to follow a private account must not disclose that stranger's display name
-- to the account's owner.
--
-- WHY `dismissed_at` IS SEPARATE FROM `read_at`
--
-- Reading a notification says "I have seen this"; dismissing it says "take
-- this off my list". They are different acts, and one does not imply the
-- other.
--
-- `dismissed_at` also means "no longer active" in general — the system sets
-- it too, when a follow request is resolved and the owner's request
-- notification is no longer outstanding. Either way the row is KEPT: the
-- record of what happened to an account is not lost by tidying the inbox.
--
-- Apply with:  supabase db push        (CLI, linked project)
--           or: paste into the Supabase SQL editor
--
-- This migration is additive and safe to re-run.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- The table
-- -----------------------------------------------------------------------------
--
-- The event types are a closed set, enforced by a CHECK constraint rather
-- than by convention, so a typo cannot become a type the interface does not
-- know how to render.
--
create table if not exists public.notifications (
  id            uuid primary key default gen_random_uuid(),

  -- The account being notified. It is the owner of the row: only this
  -- account may read it, and only this account may change it.
  recipient_id  uuid not null
                references auth.users (id) on delete cascade,

  -- The account that caused the event.
  --
  -- `on delete cascade` is the right direction here: the notification is
  -- ABOUT the actor, so when the actor's account is gone the notification
  -- has nothing left to point at.
  actor_id      uuid not null
                references auth.users (id) on delete cascade,

  -- The event.
  type          text not null
                check (type in (
                  'follow',
                  'follow_request',
                  'follow_accepted',
                  'follow_declined',
                  'comment'
                )),

  -- The follow edge, when the event is about one.
  follow_id     uuid
                references public.follows (id) on delete cascade,

  -- The comment, when the event is about one.
  comment_id    uuid
                references public.profile_comments (id) on delete cascade,

  -- The one-line description, built by the database when the event happens.
  body          text not null,

  -- The actor's handle, frozen at the moment of the event.
  actor_username text not null,

  -- The recipient's handle, frozen at the moment of the event.
  --
  -- The recipient is the account the event happened TO: the account that was
  -- followed, the account whose request was resolved, the account whose
  -- profile carries the comment. A comment notification links there.
  target_username text not null,

  created_at    timestamptz not null default now(),

  -- When the recipient read it. NULL means unread.
  read_at       timestamptz,

  -- When it stopped being shown. NULL means still on the list.
  dismissed_at  timestamptz,

  -- Nobody notifies themselves.
  check (recipient_id <> actor_id),

  -- A follow event names a follow edge, and nothing else. A comment event
  -- names a comment, and nothing else.
  check (
    (type in ('follow', 'follow_request', 'follow_accepted', 'follow_declined')
      and follow_id is not null
      and comment_id is null)
    or
    (type = 'comment' and comment_id is not null and follow_id is null)
  )
);

-- The notification centre lists a recipient's notifications, newest first.
--
-- The index is on (recipient_id, created_at desc) because that is exactly
-- the query the centre runs, and it is partial on the rows the list shows:
-- a dismissed notification is not on the list, and keeping it out of the
-- index means the index holds only what is actually read.
create index if not exists notifications_recipient_idx
  on public.notifications (recipient_id, created_at desc)
  where dismissed_at is null;

-- The unread count.
--
-- Partial on `read_at is null`, so the index holds only the unread rows.
-- The badge asks "how many are unread", and that is the only question the
-- index answers.
create index if not exists notifications_unread_idx
  on public.notifications (recipient_id, created_at desc)
  where read_at is null and dismissed_at is null;

-- -----------------------------------------------------------------------------
-- THE DUPLICATE RULE
-- -----------------------------------------------------------------------------
--
-- The brief requires that a repeated or retried event does not produce a
-- second notification.
--
-- The guarantee is a UNIQUE constraint on the EVENT, not on the pair of
-- accounts. A unique constraint on (recipient, actor, type) would be wrong:
-- somebody may follow, unfollow, and follow again, and the second follow is
-- a real, separate event that deserves its own notification.
--
-- So the constraint is on the thing the event happened TO, together with the
-- KIND of event:
--
--   a follow event   -> that follow edge, that kind of event, once
--   a comment event  -> that comment, once
--
-- The type is part of the key because ONE edge can carry several events over
-- its life. The requester's edge is the SAME row from the moment they ask,
-- through the owner's decision, to a second ask — the state machine moves
-- that row back to 'pending' rather than inserting a second one — so the
-- request, the approval and the decline are three events on one edge.
--
-- THE INDEX IS PARTIAL ON THE LIVE ROWS
--
-- Only a notification that is still ON THE LIST can block another one.
--
-- That is what makes a second ask work: when the owner resolves a request,
-- the owner's request notification is dismissed, because it is no longer
-- outstanding — and a dismissed row does not occupy the index, so the second
-- ask creates a fresh notification instead of colliding with the first.
--
-- It also means the guarantee is the useful one: an event can never produce
-- two notifications that are BOTH SHOWING. A duplicate that a retry slipped
-- in would double the list and the unread count; a duplicate that has been
-- dismissed is not showing at all.
--
-- The two indexes are separate because the two references live in different
-- columns, and a partial unique index only covers the rows it names.
--
create unique index if not exists notifications_unique_follow_event
  on public.notifications (follow_id, type)
  where follow_id is not null and dismissed_at is null;

create unique index if not exists notifications_unique_comment_event
  on public.notifications (comment_id)
  where comment_id is not null and dismissed_at is null;

-- -----------------------------------------------------------------------------
-- THE WRITE
-- -----------------------------------------------------------------------------
--
-- One function, used by every event.
--
-- It is the single place a notification is created, so the rules that apply
-- to every notification are written once:
--
--   1. nobody notifies themselves;
--   2. a blocked pair generates nothing in either direction;
--   3. the event's reference must be present, and the type must match it;
--   4. the text and the handles are built from the database's own rows;
--   5. a duplicate event is discarded rather than doubled.
--
-- Rule 2 is the one that needs care. `is_blocked_between` is SECURITY
-- DEFINER, so it sees the block even though the recipient's own RLS would
-- hide it — which is exactly what is wanted, because the question here is
-- whether a block EXISTS, not whether the recipient can see it.
--
-- Rule 5 is handled by the unique indexes rather than by a SELECT, so two
-- concurrent notifications for the same event cannot both be written: the
-- second one hits the constraint. The conflict is swallowed, because a
-- duplicate is not an error — it is the same event arriving twice.
--
create or replace function public.record_notification(
  recipient_uuid uuid,
  actor_uuid uuid,
  event_type text,
  follow_uuid uuid default null,
  comment_uuid uuid default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_handle text;
  target_handle text;
begin
  -- Nobody notifies themselves.
  if recipient_uuid is null or actor_uuid is null then
    return;
  end if;
  if recipient_uuid = actor_uuid then
    return;
  end if;

  -- A blocked pair generates nothing, in either direction. A block has to
  -- silence the relationship, and a notification is part of the relationship.
  if coalesce(public.is_blocked_between(recipient_uuid, actor_uuid), false) then
    return;
  end if;

  -- The reference must be present, and the type must match it. The table's
  -- CHECK constraint enforces this too; catching it here means a mistyped
  -- event is discarded rather than raising inside somebody else's trigger and
  -- failing the action that caused it.
  if event_type = 'comment' then
    if comment_uuid is null or follow_uuid is not null then
      return;
    end if;
  else
    if follow_uuid is null or comment_uuid is not null then
      return;
    end if;
  end if;

  -- The two handles, resolved with the definer's rights.
  --
  -- They have to be the definer's rights: either account's profile may be
  -- private, and the recipient is entitled to know that the event happened
  -- and who caused it, but not to read the actor's profile. A handle is the
  -- one piece of an account that is public by construction, so it is the one
  -- piece that travels in the notification.
  actor_handle := coalesce(
    (select p.username from public.profiles p where p.user_id = actor_uuid),
    'Someone'
  );

  target_handle := coalesce(
    (select p.username from public.profiles p where p.user_id = recipient_uuid),
    'Someone'
  );

  insert into public.notifications (
    recipient_id,
    actor_id,
    type,
    follow_id,
    comment_id,
    body,
    actor_username,
    target_username
  )
  values (
    recipient_uuid,
    actor_uuid,
    event_type,
    follow_uuid,
    comment_uuid,
    case event_type
      when 'follow' then actor_handle || ' followed you.'
      when 'follow_request' then actor_handle || ' asked to follow you.'
      when 'follow_accepted' then actor_handle || ' accepted your follow request.'
      when 'follow_declined' then actor_handle || ' declined your follow request.'
      when 'comment' then actor_handle || ' commented on your profile.'
      else actor_handle || ' interacted with you.'
    end,
    actor_handle,
    target_handle
  )
  on conflict do nothing;
end;
$$;

-- -----------------------------------------------------------------------------
-- THE FOLLOW EVENTS
-- -----------------------------------------------------------------------------
--
-- FOUR events come from the `follows` table, and each one is written by a
-- trigger that runs in the same transaction as the action that caused it.
--
--   'follow'          somebody followed a PUBLIC account
--   'follow_request'  somebody asked to follow a PRIVATE account
--   'follow_accepted' the owner approved the request
--   'follow_declined' the owner refused it
--
-- WHY THE INSERT TRIGGER CHOOSES BETWEEN TWO EVENTS
--
-- The status of a NEW edge is derived by `follows_guard_insert`, which runs
-- BEFORE this trigger and has already set the status to 'accepted' or
-- 'pending' according to the target's visibility. So this trigger does not
-- decide anything — it reads the status the database has already decided and
-- reports the matching event.
--
-- That is what makes the event correct by construction. A trigger that asked
-- "is the target public?" itself would be a second, independent copy of the
-- same rule, and the two could disagree.
--
-- WHY THE UPDATE TRIGGER ONLY FIRES ON REAL TRANSITIONS
--
-- 'accepted' and 'declined' are the only transitions that are news to the
-- REQUESTER. A 'cancelled' edge is the requester withdrawing their own
-- request, which they already know about, and the brief says not to notify
-- for it. The trigger therefore only fires when the status actually CHANGES,
-- and the notification goes to the FOLLOWER — the person whose request was
-- resolved.
--
create or replace function public.notify_follow_inserted()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.status = 'accepted' then
    perform public.record_notification(
      new.following_id,
      new.follower_id,
      'follow',
      new.id,
      null
    );
  elsif new.status = 'pending' then
    perform public.record_notification(
      new.following_id,
      new.follower_id,
      'follow_request',
      new.id,
      null
    );
  end if;

  return new;
end;
$$;

drop trigger if exists follows_notify_insert on public.follows;
create trigger follows_notify_insert
  after insert on public.follows
  for each row
  execute function public.notify_follow_inserted();

create or replace function public.notify_follow_resolved()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Only a real transition is news. An unchanged status is not a transition,
  -- and a retried approval lands here with the status already set.
  if new.status = old.status then
    return new;
  end if;

  if new.status = 'accepted' then
    perform public.record_notification(
      new.follower_id,
      new.following_id,
      'follow_accepted',
      new.id,
      null
    );
  elsif new.status = 'declined' then
    perform public.record_notification(
      new.follower_id,
      new.following_id,
      'follow_declined',
      new.id,
      null
    );
  elsif new.status = 'pending' then
    /*
     * A SECOND ASK.
     *
     * The requester is re-requesting after a decline or a withdrawal, which
     * moves the SAME edge back to 'pending'. That is a genuinely new event —
     * somebody asked again — so it notifies the owner afresh.
     *
     * The owner's previous request notification was dismissed when the
     * request was resolved, so it no longer occupies the unique index and
     * this insert is not a duplicate.
     */
    perform public.record_notification(
      new.following_id,
      new.follower_id,
      'follow_request',
      new.id,
      null
    );
  end if;

  return new;
end;
$$;

drop trigger if exists follows_notify_update on public.follows;
create trigger follows_notify_update
  after update on public.follows
  for each row
  execute function public.notify_follow_resolved();

-- -----------------------------------------------------------------------------
-- A RESOLVED REQUEST IS NO LONGER OUTSTANDING
-- -----------------------------------------------------------------------------
--
-- When the owner approves or declines a request, the owner's own notification
-- — "Carol asked to follow you" — stops being true. Carol is now a
-- follower, or the request is closed.
--
-- So it is dismissed, by the system, at the moment the request is resolved.
-- The row is kept, so the record of the request is not lost.
--
-- This is also what lets a SECOND ASK notify: the dismissed row does not
-- occupy the unique index, so the new request notification is a new event
-- rather than a collision with the first.
--
create or replace function public.notify_follow_request_closed()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.status in ('accepted', 'declined')
     and old.status = 'pending'
     and new.status <> old.status then
    update public.notifications
    set dismissed_at = now()
    where follow_id = new.id
      and type = 'follow_request'
      and dismissed_at is null;
  end if;

  return new;
end;
$$;

drop trigger if exists follows_notify_request_closed on public.follows;
create trigger follows_notify_request_closed
  after update on public.follows
  for each row
  execute function public.notify_follow_request_closed();

-- -----------------------------------------------------------------------------
-- THE COMMENT EVENT
-- -----------------------------------------------------------------------------
--
-- A comment on a profile notifies the profile's OWNER.
--
-- It does not notify the commenter, and it does not notify anybody who
-- happens to follow the profile. The event is about the profile, and the
-- profile has one owner.
--
-- The notification does NOT carry the comment's text. A comment on a private
-- profile is readable only by approved followers, and the notification is a
-- summary of it — the recipient reads the comment itself, on the profile,
-- under the rules that already apply. A notification that carried the text
-- would hand the comment to the profile's owner in a place where the reader
-- cannot check who else may read it.
--
create or replace function public.notify_comment_created()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.record_notification(
    new.profile_id,
    new.author_id,
    'comment',
    null,
    new.id
  );

  return new;
end;
$$;

drop trigger if exists profile_comments_notify on public.profile_comments;
create trigger profile_comments_notify
  after insert on public.profile_comments
  for each row
  execute function public.notify_comment_created();

-- -----------------------------------------------------------------------------
-- A BLOCK SILENCES THE NOTIFICATIONS THAT ALREADY EXIST
-- -----------------------------------------------------------------------------
--
-- A block has to do more than stop future notifications. A notification that
-- is already in the recipient's list tells them that the blocked account
-- followed them, commented on them, or asked to follow them — and a block is
-- precisely the act of saying "I do not want to hear from this account".
--
-- So a block DISCARDS the notifications between the pair, in both
-- directions. The rows are deleted rather than hidden, because a dismissed
-- notification is still a record that the recipient can read through their
-- own history; a discarded one is gone.
--
-- The trigger runs AFTER the insert, so the block row already exists when
-- the delete runs, and the pair is known to be blocked.
--
create or replace function public.user_blocks_discards_notifications()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  delete from public.notifications
  where (recipient_id = new.blocker_id and actor_id = new.blocked_id)
     or (recipient_id = new.blocked_id and actor_id = new.blocker_id);

  return new;
end;
$$;

drop trigger if exists user_blocks_discard_notifications on public.user_blocks;
create trigger user_blocks_discard_notifications
  after insert on public.user_blocks
  for each row
  execute function public.user_blocks_discards_notifications();

-- -----------------------------------------------------------------------------
-- RLS
-- -----------------------------------------------------------------------------
--
-- The rules, stated once:
--
--   - ONLY the recipient reads a notification;
--   - ONLY the recipient changes one;
--   - NO client role CREATES one.
--
-- The last one is the important one. A notification is written by a trigger,
-- as the table's owner, and the trigger's writes bypass RLS because the
-- owner holds the rows. A client that could INSERT into this table could
-- write a notification to somebody else's inbox — telling an account that
-- somebody it blocked had followed it, or that a comment existed that did
-- not. So there is NO INSERT policy at all, and the table's INSERT privilege
-- is revoked from every client role.
--
-- The UPDATE policy is scoped to the recipient AND carries a `with check`
-- that keeps the recipient the same, so a recipient can mark a notification
-- read or dismiss it, and cannot re-point it at somebody else.
--
alter table public.notifications enable row level security;

drop policy if exists "recipients can read their notifications" on public.notifications;
create policy "recipients can read their notifications"
  on public.notifications
  for select
  to authenticated
  using ((select auth.uid()) = recipient_id);

drop policy if exists "recipients can update their notifications" on public.notifications;
create policy "recipients can update their notifications"
  on public.notifications
  for update
  to authenticated
  using ((select auth.uid()) = recipient_id)
  with check ((select auth.uid()) = recipient_id);

-- There is deliberately NO insert policy and NO delete policy. A client role
-- cannot create a notification for anybody, and cannot delete one. The
-- trigger writes as the owner; the recipient dismisses with an UPDATE.

-- -----------------------------------------------------------------------------
-- THE PRIVILEGE LOCK
-- -----------------------------------------------------------------------------
--
-- The same shape as migration 0009 and 00013: revoke first, then grant
-- exactly what the application needs, and nothing more.
--
-- `anon` gets nothing. An anonymous visitor has no notifications.
--
revoke all on table public.notifications from public, anon, authenticated;
grant select, update on table public.notifications to authenticated;

-- The write functions are SECURITY DEFINER. A client role that can EXECUTE
-- one can call it directly, with the definer's rights, to write a
-- notification into somebody else's inbox. They are revoked from every
-- client role.
--
-- Revoking EXECUTE does NOT stop a trigger from firing: Postgres checks a
-- trigger function's EXECUTE privilege when the TRIGGER is created, and
-- firing it runs it with the table owner's rights regardless of who called
-- the DML.
--
revoke all on function public.record_notification(uuid, uuid, text, uuid, uuid) from public, anon, authenticated;
revoke all on function public.notify_follow_inserted() from public, anon, authenticated;
revoke all on function public.notify_follow_resolved() from public, anon, authenticated;
revoke all on function public.notify_follow_request_closed() from public, anon, authenticated;
revoke all on function public.notify_comment_created() from public, anon, authenticated;
revoke all on function public.user_blocks_discards_notifications() from public, anon, authenticated;

-- The trigger functions are called by the database, never by a client, and
-- they are revoked from every client role for the same reason.
--
grant execute on function public.record_notification(uuid, uuid, text, uuid, uuid) to postgres;
grant execute on function public.notify_follow_inserted() to postgres;
grant execute on function public.notify_follow_resolved() to postgres;
grant execute on function public.notify_follow_request_closed() to postgres;
grant execute on function public.notify_comment_created() to postgres;
grant execute on function public.user_blocks_discards_notifications() to postgres;
